package com.yilu.yinling.security;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.yilu.yinling.user.entity.User; import com.yilu.yinling.user.mapper.UserMapper; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service @org.springframework.context.annotation.Profile("!demo") public class UserDetailsServiceImpl implements UserDetailsService { private final UserMapper mapper; public UserDetailsServiceImpl(UserMapper mapper){this.mapper=mapper;} public UserDetails loadUserByUsername(String username){User u=mapper.selectOne(new QueryWrapper<User>().eq("username",username));if(u==null)throw new UsernameNotFoundException(username);return org.springframework.security.core.userdetails.User.withUsername(u.getUsername()).password(u.getPassword()).authorities("ROLE_USER").disabled(u.getStatus()!=null&&u.getStatus()==0).build();} }
